"use client"

import { useCallback, useEffect, useRef, useState } from "react"

import {
  alreadyLiveDialed,
  fetchCase,
  fetchEvents,
  openCase,
  placeLiveCall,
  sessionFromEvents,
} from "@/lib/live/api"
import {
  outreachIsLive,
  pickLiveCallSupplier,
  resolveChecklist,
} from "@/lib/live/checklist"
import { EVENT_POLL_MS, HOLD_FOR, PART_ID } from "@/lib/live/config"
import { fetchPlan, type LivePlan } from "@/lib/live/plan"
import type {
  CaseEvent,
  CaseSnapshot,
  LiveCandidate,
  OpenedCase,
  SessionInfo,
} from "@/lib/live/types"

export type DevinCaseStatus =
  | "idle"
  | "launching"
  | "live"
  | "stubbed"
  | "error"

type DevinCaseState = {
  status: DevinCaseStatus
  error: string | null
  caseId: string | null
  snapshot: CaseSnapshot | null
  events: CaseEvent[]
  plan: LivePlan | null
  session: SessionInfo | null
}

const EMPTY: DevinCaseState = {
  status: "idle",
  error: null,
  caseId: null,
  snapshot: null,
  events: [],
  plan: null,
  session: null,
}

function statusFromSession(session: SessionInfo | null): DevinCaseStatus {
  if (!session) return "live"
  return session.stubbed ? "stubbed" : "live"
}

export function useDevinCase(caseIdFromUrl: string | null) {
  const [state, setState] = useState<DevinCaseState>(EMPTY)

  const attach = useCallback(async (caseId: string, opened?: OpenedCase) => {
    const [snapshot, events, plan] = await Promise.all([
      fetchCase(caseId),
      fetchEvents(caseId),
      fetchPlan(caseId),
    ])
    const session =
      opened !== undefined
        ? {
            session_id: opened.session_id,
            session_url: opened.session_url,
            stubbed: opened.stubbed,
            error: opened.session_error,
          }
        : sessionFromEvents(events)
    setState({
      status: statusFromSession(session),
      error: session?.error ?? null,
      caseId,
      snapshot,
      events,
      plan,
      session,
    })
  }, [])

  const launch = useCallback(async () => {
    setState({ ...EMPTY, status: "launching" })
    try {
      const opened = await openCase(PART_ID)
      await attach(opened.case_id, opened)
      return opened.case_id
    } catch (cause) {
      const message =
        cause instanceof Error ? cause.message : "Could not open a case"
      setState({ ...EMPTY, status: "error", error: message })
      return null
    }
  }, [attach])

  useEffect(() => {
    if (!caseIdFromUrl) return
    let cancelled = false

    const load = async () => {
      try {
        await attach(caseIdFromUrl)
      } catch (cause) {
        if (cancelled) return
        const message =
          cause instanceof Error ? cause.message : "Could not load the case"
        setState({ ...EMPTY, status: "error", error: message })
      }
    }

    void load()
    return () => {
      cancelled = true
    }
  }, [attach, caseIdFromUrl])

  const eventsRef = useRef<CaseEvent[]>([])
  eventsRef.current = state.events

  useEffect(() => {
    const caseId = state.caseId
    if (!caseId || state.status === "error" || state.status === "launching") {
      return
    }
    let cancelled = false

    const tick = async () => {
      try {
        const since = eventsRef.current.at(-1)?.seq ?? 0
        const [snapshot, fresh, plan] = await Promise.all([
          fetchCase(caseId),
          fetchEvents(caseId, since),
          fetchPlan(caseId),
        ])
        if (cancelled) return
        setState((current) => {
          if (current.caseId !== caseId) return current
          const events =
            fresh.length > 0 ? [...current.events, ...fresh] : current.events
          const session = sessionFromEvents(events) ?? current.session
          return {
            ...current,
            snapshot,
            events,
            plan,
            session,
            status: statusFromSession(session),
            error: session?.error ?? current.error,
          }
        })
      } catch {
        // Keep the last good feed. The next tick retries.
      }
    }

    const interval = window.setInterval(() => void tick(), EVENT_POLL_MS)
    return () => {
      cancelled = true
      window.clearInterval(interval)
    }
  }, [state.caseId, state.status])

  const candidates: readonly LiveCandidate[] = state.snapshot?.candidates ?? []
  const checklist = state.plan
    ? resolveChecklist(state.plan, candidates)
    : null

  useEffect(() => {
    const caseId = state.caseId
    if (!caseId || !checklist) return
    if (!outreachIsLive(checklist)) return
    if (alreadyLiveDialed(state.events)) return
    const supplierRef = pickLiveCallSupplier(checklist, candidates, HOLD_FOR)
    if (!supplierRef) return
    void placeLiveCall(caseId, supplierRef).catch((cause) => {
      const message =
        cause instanceof Error ? cause.message : "Live call failed"
      setState((current) =>
        current.caseId === caseId
          ? { ...current, error: message }
          : current
      )
    })
  }, [candidates, checklist, state.caseId, state.events])

  return {
    ...state,
    candidates,
    checklist,
    launch,
    running: state.status === "launching" || state.status === "live",
  }
}
import {
  CheckIcon,
  CircleIcon,
  Loader2Icon,
  Phone,
  XIcon,
} from "@/components/icons"
import { DotLoader } from "@/components/cockpit/dot-loader"
import type { LivePlan, LivePlanStep, LiveStepStatus } from "@/lib/live/plan"
import { cn } from "@/lib/utils"

export function PlanChecklist({
  plan,
  launching,
}: {
  plan: LivePlan | null
  launching: boolean
}) {
  if (launching && !plan) {
    return (
      <div className="flex items-center gap-2 text-sm text-muted-foreground">
        <DotLoader className="size-4" />
        <span>Opening the case…</span>
      </div>
    )
  }

  if (!plan) {
    return (
      <p className="text-sm text-muted-foreground">
        No checklist yet. It appears when the case opens.
      </p>
    )
  }

  const percent = plan.total ? Math.round((plan.done / plan.total) * 100) : 0
  const liveCalls = plan.sections
    .flatMap((section) => section.steps)
    .filter(
      (step) =>
        step.group === "outreach" &&
        step.supplier_ref &&
        step.status === "active"
    )

  return (
    <div className="flex flex-col gap-8">
      <header className="flex flex-col gap-3">
        <div className="flex items-baseline justify-between gap-3">
          <h2 className="text-sm font-medium">What the agent is doing</h2>
          <p className="font-mono text-xs text-muted-foreground tabular-nums">
            {plan.done}/{plan.total}
          </p>
        </div>
        <div className="h-px overflow-hidden bg-border/70">
          <div
            className="h-full bg-foreground/80 transition-[width] duration-500 ease-out"
            style={{ width: `${percent}%` }}
          />
        </div>
      </header>

      <ol className="flex flex-col gap-7">
        {plan.sections.map((section) => {
          const status = section.status ?? "pending"
          return (
          <li key={section.group} className="flex flex-col gap-2.5">
            <div className="flex items-center gap-2">
              <span
                aria-hidden="true"
                className={cn(
                  "size-1.5 rounded-full",
                  status === "done" && "bg-foreground",
                  status === "active" && "bg-foreground/70",
                  status === "failed" && "bg-destructive",
                  (status === "pending" || status === "skipped") &&
                    "bg-muted-foreground/30"
                )}
              />
              <h3
                className={cn(
                  "text-[13px] font-medium",
                  status === "pending"
                    ? "text-muted-foreground"
                    : "text-foreground"
                )}
              >
                {section.label}
              </h3>
            </div>
            <ul className="ml-2 flex flex-col border-l border-border/70 pl-4">
              {section.steps.length === 0 ? (
                <li className="py-1.5 text-[13px] text-muted-foreground">
                  {section.group === "outreach"
                    ? "Waiting for Devin to name who to call."
                    : "Not started."}
                </li>
              ) : (
                section.steps.map((step) => (
                  <StepRow key={step.step_id} step={step} />
                ))
              )}
            </ul>
            {section.group === "outreach" && liveCalls.length > 1 ? (
              <p className="ml-6 text-[11px] text-muted-foreground">
                {liveCalls.length} shown in parallel. One live dial to the demo
                number.
              </p>
            ) : null}
          </li>
          )
        })}
      </ol>
    </div>
  )
}

function StepRow({ step }: { step: LivePlanStep }) {
  const calling = Boolean(step.supplier_ref && step.group === "outreach")
  const Icon = iconFor(step.status, calling)

  return (
    <li className="flex items-start gap-2.5 py-1.5">
      <Icon
        aria-hidden="true"
        className={cn(
          "mt-0.5 size-3.5 shrink-0",
          toneFor(step.status),
          step.status === "active" && !calling && "animate-spin"
        )}
      />
      <div className="min-w-0">
        <p
          className={cn(
            "text-sm leading-5",
            step.status === "pending" && "text-muted-foreground",
            step.status === "active" && "text-foreground",
            step.status === "done" && "text-foreground/80",
            step.status === "failed" && "text-destructive",
            step.status === "skipped" && "text-muted-foreground line-through"
          )}
        >
          {step.label}
        </p>
        {step.detail ? (
          <p className="mt-0.5 text-xs leading-5 text-muted-foreground">
            {step.detail}
          </p>
        ) : step.status === "active" && calling ? (
          <p className="mt-0.5 text-xs leading-5 text-muted-foreground">
            Dialing…
          </p>
        ) : null}
      </div>
    </li>
  )
}

function iconFor(status: LiveStepStatus, calling: boolean) {
  if (status === "active" && calling) return Phone
  if (status === "active") return Loader2Icon
  if (status === "done") return CheckIcon
  if (status === "failed") return XIcon
  return CircleIcon
}

function toneFor(status: LiveStepStatus): string {
  if (status === "active") return "text-foreground"
  if (status === "done") return "text-foreground/70"
  if (status === "failed") return "text-destructive"
  return "text-muted-foreground/50"
}
import type { LivePlan, LivePlanSection, LivePlanStep } from "@/lib/live/plan"
import type { LiveCandidate } from "@/lib/live/types"

/** Overlay Devin's candidate list onto the seeded plan.
 *
 * Fixed headers stay. Call lines are whoever Devin named, not a baked-in
 * supplier set. Once outreach starts, unfinished call rows go active together
 * so the screen reads as a parallel fan-out. The backend still routes every
 * live dial to DEMO_CALL_DESTINATION.
 */
export function resolveChecklist(
  plan: LivePlan,
  candidates: readonly LiveCandidate[]
): LivePlan {
  const passed = candidates.filter((candidate) => candidate.compliance.passed)
  const outreach = plan.sections.find((section) => section.group === "outreach")
  const callingNow = outreachStarted(outreach)

  const sections = plan.sections.map((section) => {
    if (section.group === "screening") {
      return mergeSupplierRows(section, candidates, screeningRow, false)
    }
    if (section.group === "outreach") {
      return mergeSupplierRows(section, passed, callingRow, callingNow)
    }
    return section
  })

  const steps = sections.flatMap((section) => section.steps)
  return {
    ...plan,
    sections,
    done: steps.filter((step) => isFinished(step.status)).length,
    total: steps.length,
    active_step_id:
      steps.find((step) => step.status === "active")?.step_id ??
      plan.active_step_id,
  }
}

export function pickLiveCallSupplier(
  plan: LivePlan | null,
  candidates: readonly LiveCandidate[],
  holdFor = ""
): string | null {
  if (holdFor) return holdFor
  const passed = candidates.find((candidate) => candidate.compliance.passed)
  if (passed) return passed.supplier_ref
  const calling = plan?.sections
    .find((section) => section.group === "outreach")
    ?.steps.find((step) => step.supplier_ref && step.status === "active")
  return calling?.supplier_ref ?? null
}

export function outreachIsLive(plan: LivePlan | null): boolean {
  if (!plan) return false
  return outreachStarted(
    plan.sections.find((section) => section.group === "outreach")
  )
}

function outreachStarted(section: LivePlanSection | undefined): boolean {
  if (!section) return false
  if (section.status === "active") return true
  return section.steps.some(
    (step) =>
      step.status === "active" ||
      (step.step_id === "outreach:brief" && isFinished(step.status))
  )
}

function mergeSupplierRows(
  section: LivePlanSection,
  suppliers: readonly LiveCandidate[],
  build: (candidate: LiveCandidate, existing?: LivePlanStep) => LivePlanStep,
  forceActive: boolean
): LivePlanSection {
  const fixed = section.steps.filter((step) => !step.supplier_ref)
  const byRef = new Map(
    section.steps
      .filter((step) => step.supplier_ref)
      .map((step) => [step.supplier_ref, step])
  )

  const fromDevin = suppliers.map((candidate) => {
    const row = build(candidate, byRef.get(candidate.supplier_ref))
    byRef.delete(candidate.supplier_ref)
    if (forceActive && row.status === "pending") {
      return { ...row, status: "active" as const }
    }
    return row
  })

  const leftover = [...byRef.values()].map((step) =>
    forceActive && step.status === "pending"
      ? { ...step, status: "active" as const }
      : step
  )

  const steps = [...fixed, ...fromDevin, ...leftover]
  return {
    ...section,
    steps,
    status: sectionStatus(steps),
  }
}

function screeningRow(
  candidate: LiveCandidate,
  existing?: LivePlanStep
): LivePlanStep {
  if (existing) return existing
  return {
    step_id: `screening:${candidate.supplier_ref}`,
    group: "screening",
    label: candidate.supplier_name,
    status: candidate.compliance.passed ? "done" : "failed",
    detail: candidate.compliance.passed
      ? "Passed procurement policy"
      : candidate.compliance.failed_rules.join(", ") || "Rejected",
    supplier_ref: candidate.supplier_ref,
    dynamic: true,
    started_at: null,
    completed_at: null,
  }
}

function callingRow(
  candidate: LiveCandidate,
  existing?: LivePlanStep
): LivePlanStep {
  if (existing) {
    return {
      ...existing,
      label: existing.label || `Calling ${candidate.supplier_name}`,
    }
  }
  return {
    step_id: `outreach:${candidate.supplier_ref}`,
    group: "outreach",
    label: `Calling ${candidate.supplier_name}`,
    status: "pending",
    detail: null,
    supplier_ref: candidate.supplier_ref,
    dynamic: true,
    started_at: null,
    completed_at: null,
  }
}

function isFinished(status: LivePlanStep["status"]): boolean {
  return status === "done" || status === "failed" || status === "skipped"
}

function sectionStatus(steps: LivePlanStep[]): LivePlanSection["status"] {
  if (steps.some((step) => step.status === "active")) return "active"
  if (steps.some((step) => step.status === "failed") && steps.every(isFinished)) {
    return "failed"
  }
  if (steps.length > 0 && steps.every((step) => isFinished(step.status))) {
    return "done"
  }
  return "pending"
}
