"use client"

import { useEffect, useState } from "react"
import { usePathname, useRouter, useSearchParams } from "next/navigation"
import {
  DesktopCallLayout,
  MobileCallLayout,
  type MobilePane,
} from "@/components/cockpit/call-layout"
import { HistoryIcon, TranscriptIcon, XIcon } from "@/components/icons"
import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@/components/ui/dialog"
import { CALLS, type CallingAgentRun, type RehearsalCall } from "@/lib/case-001"

const WIDE_CALL_LAYOUT = "(min-width: 64rem)"

export function CallDetailDialog({
  agentRuns,
}: {
  agentRuns: readonly CallingAgentRun[]
}) {
  const pathname = usePathname()
  const router = useRouter()
  const searchParams = useSearchParams()
  const mockRequested = searchParams.get("mock") === "true"
  const selectedCallId = searchParams.get("call")
  const baseCall =
    CALLS.find((candidate) => candidate.id === selectedCallId) ??
    (mockRequested ? CALLS[0] : undefined)
  const agentRun = selectedCallId
    ? agentRuns.find((agent) => agent.callId === selectedCallId)
    : undefined
  const call: RehearsalCall | undefined =
    baseCall && agentRun
      ? {
          ...baseCall,
          status:
            agentRun.phase === "complete"
              ? baseCall.status
              : agentRun.phase === "calling"
                ? "calling"
                : "dialing",
          duration: agentRun.durationLabel,
          runtimeAgentName: agentRun.name,
          runtimeStartedAt:
            agentRun.startedAt === null
              ? undefined
              : new Date(agentRun.startedAt).toISOString(),
          visibleTranscriptTurnCount: agentRun.visibleTranscriptTurnCount,
        }
      : baseCall
  const [historyOpen, setHistoryOpen] = useState(true)
  const [transcriptOpen, setTranscriptOpen] = useState(true)
  const [mobilePane, setMobilePane] = useState<MobilePane>("call")
  const [isWide, setIsWide] = useState(false)

  useEffect(() => {
    const media = window.matchMedia(WIDE_CALL_LAYOUT)
    const update = () => setIsWide(media.matches)

    update()
    media.addEventListener("change", update)
    return () => media.removeEventListener("change", update)
  }, [])

  function closeDialog() {
    const nextParams = new URLSearchParams(searchParams.toString())
    nextParams.delete("call")
    nextParams.delete("mock")
    const query = nextParams.toString()

    router.replace(query ? `${pathname}?${query}` : pathname, { scroll: false })
  }

  function toggleHistory() {
    if (isWide) setHistoryOpen((open) => !open)
    else setMobilePane((pane) => (pane === "history" ? "call" : "history"))
  }

  function toggleTranscript() {
    if (isWide) setTranscriptOpen((open) => !open)
    else {
      setMobilePane((pane) => (pane === "transcript" ? "call" : "transcript"))
    }
  }

  if (!call) return null

  const historyVisible = isWide ? historyOpen : mobilePane === "history"
  const transcriptVisible = isWide
    ? transcriptOpen
    : mobilePane === "transcript"

  return (
    <Dialog open onOpenChange={(open) => !open && closeDialog()}>
      <DialogContent
        showCloseButton={false}
        className="flex h-dvh max-h-none w-screen max-w-none flex-col gap-0 overflow-hidden rounded-none p-0 sm:max-w-none lg:h-[calc(100dvh-2rem)] lg:w-[calc(100vw-2rem)] lg:rounded-xl"
      >
        <header className="grid h-12 shrink-0 grid-cols-[1fr_minmax(0,auto)_1fr] items-center border-b border-border px-2 sm:px-3">
          <div className="flex min-w-0 justify-start">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              aria-label="Toggle call history"
              aria-pressed={historyVisible}
              onClick={toggleHistory}
            >
              <HistoryIcon data-icon="inline-start" />
              <span className="hidden sm:inline">History</span>
            </Button>
          </div>
          <DialogTitle className="min-w-0 truncate px-2 text-center text-sm">
            {call.supplier}
          </DialogTitle>
          <DialogDescription className="sr-only">
            Rehearsal call with connected history, animated voice state, and a
            transcript.
          </DialogDescription>
          <div className="flex min-w-0 items-center justify-end gap-1">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              aria-label="Toggle transcript"
              aria-pressed={transcriptVisible}
              onClick={toggleTranscript}
            >
              <TranscriptIcon data-icon="inline-start" />
              <span className="hidden sm:inline">Transcript</span>
            </Button>
            <DialogClose render={<Button variant="ghost" size="icon-lg" />}>
              <XIcon />
              <span className="sr-only">Close call dialog</span>
            </DialogClose>
          </div>
        </header>
        {isWide ? (
          <DesktopCallLayout
            call={call}
            historyOpen={historyOpen}
            transcriptOpen={transcriptOpen}
            onEnd={closeDialog}
          />
        ) : (
          <MobileCallLayout call={call} pane={mobilePane} onEnd={closeDialog} />
        )}
      </DialogContent>
    </Dialog>
  )
}
"use client"

import { useRouter } from "next/navigation"
import { Bot, ChevronDownIcon, XIcon } from "@/components/icons"
import { CandidateComparison } from "@/components/cockpit/candidate-comparison"
import {
  candidateLifecycleStatus,
  type CandidateLifecycleStatus,
} from "@/components/cockpit/candidate-status"
import { RejectedCandidate } from "@/components/cockpit/rejected-candidate"
import type {
  Candidate,
  CandidateState,
} from "@/components/cockpit/candidate-types"
import { Button } from "@/components/ui/button"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  CALLS,
  CANDIDATES,
  LANDED_LINES,
  SCRIPT,
  type CallingAgentRun,
} from "@/lib/case-001"
import { cn } from "@/lib/utils"

export function CandidatePanel({
  visible,
  agentRuns,
  chosenCandidateIds,
  decisionRecorded,
  onClose,
}: {
  visible: number
  agentRuns: readonly CallingAgentRun[]
  chosenCandidateIds: readonly string[]
  decisionRecorded: boolean
  onClose: () => void
}) {
  const visibleIds = new Set(SCRIPT.slice(0, visible).map((step) => step.id))
  const state: CandidateState = {
    candidatesVisible: visibleIds.has("suppliers"),
    policyComplete: visibleIds.has("policy"),
    outreachStarted: agentRuns.some((agent) => agent.phase !== "queued"),
    claimsComplete: visibleIds.has("claims"),
    costsComplete: visibleIds.has("deltas"),
    decisionRecorded,
  }
  const candidates = state.candidatesVisible ? CANDIDATES : []

  return (
    <aside
      aria-label="Candidates"
      className="flex h-full w-full min-w-0 flex-col overflow-hidden bg-sidebar text-foreground"
    >
      <header className="flex min-h-11 shrink-0 items-center justify-between border-b border-border px-3">
        <h2 className="text-sm font-medium">Candidates</h2>
        <Button
          type="button"
          size="icon-sm"
          variant="ghost"
          aria-label="Close Candidates sidebar"
          onClick={onClose}
        >
          <XIcon aria-hidden="true" />
        </Button>
      </header>
      {candidates.length === 0 ? (
        <p className="p-4 text-sm text-muted-foreground">
          No Candidates matched yet.
        </p>
      ) : (
        <div className="min-h-0 flex-1 overflow-y-auto">
          {candidates.map((candidate) => (
            <CandidateRow
              key={candidate.name}
              candidate={candidate as Candidate}
              state={state}
              agentRun={agentRuns.find(
                (agent) => agent.candidateId === candidate.id
              )}
              researchComplete={
                candidate.researchChannel === "website"
                  ? visibleIds.has(candidate.researchAfterId)
                  : agentRuns.some(
                      (agent) =>
                        agent.candidateId === candidate.id &&
                        agent.phase === "complete"
                    )
              }
              chosen={chosenCandidateIds.includes(candidate.id)}
            />
          ))}
        </div>
      )}
    </aside>
  )
}

function CandidateRow({
  candidate,
  state,
  agentRun,
  researchComplete,
  chosen,
}: {
  candidate: Candidate
  state: CandidateState
  agentRun?: CallingAgentRun
  researchComplete: boolean
  chosen: boolean
}) {
  const rejected = state.policyComplete && candidate.compliance === "failed"
  const callFixture = CALLS.find((item) => item.candidateId === candidate.id)
  const call =
    callFixture && agentRun?.phase !== "queued" ? callFixture : undefined
  const landedLine = LANDED_LINES.find(
    (line) => line.candidateId === candidate.id
  )
  const status = candidateLifecycleStatus({
    candidate,
    state,
    call,
    landedLine,
    researchComplete,
    chosen: state.decisionRecorded && chosen,
  })
  const description = candidate.supplierRecord.preferred
    ? `${candidate.country} · Preferred Supplier Record`
    : `${candidate.country} · Supplier Record`
  const candidateState = {
    ...state,
    claimsComplete: researchComplete || state.claimsComplete,
  }

  return (
    <Collapsible className="border-b border-border">
      <CollapsibleTrigger className="group flex min-h-9 w-full items-center gap-2 px-2.5 pt-1.5 pb-1 text-left outline-none hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset">
        <span className="min-w-0 flex-1">
          <span className="block truncate text-xs font-medium">
            {candidate.name}
          </span>
          <span className="block truncate text-[11px] leading-4 text-muted-foreground">
            {description}
          </span>
        </span>
        <LifecycleStatus status={status} />
        <ChevronDownIcon
          aria-hidden="true"
          className="size-3.5 shrink-0 text-muted-foreground transition-transform duration-200 ease-[cubic-bezier(0.77,0,0.175,1)] group-data-[panel-open]:rotate-180 motion-reduce:transition-none"
        />
      </CollapsibleTrigger>
      {callFixture && agentRun ? (
        <CallingAgentCard call={callFixture} agentRun={agentRun} />
      ) : null}
      <CollapsibleContent>
        <div className="border-t border-border bg-background/50 px-3 py-2.5">
          {rejected ? (
            <RejectedCandidate candidate={candidate} />
          ) : (
            <CandidateComparison
              candidate={candidate}
              state={candidateState}
              call={call}
              landedLine={landedLine}
            />
          )}
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

const STATUS_STYLES: Record<
  CandidateLifecycleStatus,
  { className: string; dotClassName: string }
> = {
  sourced: {
    className: "bg-muted-foreground/20 text-foreground",
    dotClassName: "bg-muted-foreground",
  },
  "no answer": {
    className: "bg-muted-foreground/20 text-foreground",
    dotClassName: "bg-muted-foreground",
  },
  incomplete: {
    className: "bg-chart-1/30 text-foreground",
    dotClassName: "bg-chart-1",
  },
  ready: {
    className: "bg-chart-5/30 text-foreground",
    dotClassName: "bg-chart-5",
  },
  chosen: {
    className: "bg-primary/30 text-foreground",
    dotClassName: "bg-primary",
  },
  rejected: {
    className: "bg-destructive/30 text-foreground",
    dotClassName: "bg-destructive",
  },
}

function LifecycleStatus({ status }: { status: CandidateLifecycleStatus }) {
  const style = STATUS_STYLES[status]

  return (
    <span
      className={cn(
        "inline-flex h-4.5 shrink-0 items-center gap-1 rounded-full px-1.5 text-[10px] font-medium",
        style.className
      )}
    >
      <span
        aria-hidden="true"
        className={cn("size-2 rounded-full", style.dotClassName)}
      />
      {status}
    </span>
  )
}

function CallingAgentCard({
  call,
  agentRun,
}: {
  call: (typeof CALLS)[number]
  agentRun: CallingAgentRun
}) {
  const router = useRouter()
  const active = agentRun.phase === "dialing" || agentRun.phase === "calling"
  const status =
    agentRun.phase === "dialing"
      ? "dialing..."
      : `calling · ${agentRun.durationLabel}`

  function openCall() {
    const nextParams = new URLSearchParams(window.location.search)
    nextParams.set("call", call.id)
    router.replace(`${window.location.pathname}?${nextParams.toString()}`, {
      scroll: false,
    })
  }

  return (
    <div className="candidate-agent-reveal grid px-2.5" data-visible={active}>
      <div className="min-h-0 overflow-hidden">
        <button
          type="button"
          className="candidate-agent-card mb-1.5 flex w-full items-center gap-2 rounded-full bg-background/60 p-1 pr-2 text-left transition-colors duration-150 outline-none hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none"
          onClick={openCall}
          disabled={!active}
          tabIndex={active ? 0 : -1}
          aria-hidden={!active}
          aria-label={`Open ${agentRun.name}'s call with ${call.supplier}`}
        >
          <Avatar size="sm" className="after:border-0">
            <AvatarFallback className={agentRun.avatarClassName}>
              <Bot aria-hidden="true" className="size-3.5" />
            </AvatarFallback>
          </Avatar>
          <span className="min-w-0 flex-1 truncate text-xs font-medium">
            {agentRun.name}
          </span>
          <span className="shrink-0 text-[11px] text-muted-foreground tabular-nums">
            {status}
          </span>
        </button>
      </div>
    </div>
  )
}
"use client"

import { useState } from "react"

import { CheckIcon, ChevronRightIcon } from "@/components/icons"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { CANDIDATES, LANDED_LINES } from "@/lib/case-001"
import { cn } from "@/lib/utils"

type DecisionBarProps = {
  recorded: boolean
  selectedCandidateId: string | null
  onSelectCandidate: (candidateId: string) => void
  onRecord: () => void
}

const SELECTABLE_CANDIDATES = CANDIDATES.filter((candidate) => {
  const landedLine = LANDED_LINES.find(
    (line) => line.candidateId === candidate.id
  )
  return candidate.compliance === "passed" && landedLine?.usable !== false
})

export function DecisionBar({
  recorded,
  selectedCandidateId,
  onSelectCandidate,
  onRecord,
}: DecisionBarProps) {
  const [open, setOpen] = useState(false)
  const selectedCandidate = CANDIDATES.find(
    (candidate) => candidate.id === selectedCandidateId
  )

  function recordDecision() {
    onRecord()
    setOpen(false)
  }

  return (
    <div className="mx-auto w-full max-w-[50vw] px-4 pt-3">
      <Collapsible open={open} onOpenChange={setOpen}>
        <Card
          size="sm"
          className="w-full gap-0 border border-border bg-secondary/70 py-0 ring-0"
        >
          <CollapsibleContent className="border-b border-border/70 px-3 py-3">
            <DecisionDetails
              recorded={recorded}
              selectedCandidateId={selectedCandidateId}
              onSelectCandidate={onSelectCandidate}
              onRecord={recordDecision}
            />
          </CollapsibleContent>
          <CollapsibleTrigger
            className="group flex min-h-10 w-full min-w-0 items-center gap-3 px-3 py-2 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring"
            aria-label="Toggle Decision details"
          >
            <span className="text-sm font-medium">Complete</span>
            <span className="ml-auto flex min-w-0 items-center gap-1 text-sm text-muted-foreground">
              {recorded ? (
                <>
                  <CheckIcon aria-hidden="true" className="size-3.5" />
                  <span className="truncate">
                    {selectedCandidate?.name ?? "Decision recorded"}
                  </span>
                </>
              ) : (
                <span>Take decision</span>
              )}
              <ChevronRightIcon className="size-4 shrink-0 transition-transform duration-200 ease-[cubic-bezier(0.77,0,0.175,1)] group-data-[panel-open]:rotate-90 motion-reduce:transition-none" />
            </span>
          </CollapsibleTrigger>
        </Card>
      </Collapsible>
    </div>
  )
}

function DecisionDetails({
  recorded,
  selectedCandidateId,
  onSelectCandidate,
  onRecord,
}: DecisionBarProps) {
  return (
    <div className="text-sm">
      <p className="font-medium">Choose a Candidate</p>
      <p className="mt-1 text-xs text-muted-foreground">
        Compare Claims and Supplier Records before you record the Decision.
      </p>
      <div className="mt-3 grid gap-1.5" role="radiogroup">
        {SELECTABLE_CANDIDATES.map((candidate) => {
          const selected = selectedCandidateId === candidate.id
          const landedLine = LANDED_LINES.find(
            (line) => line.candidateId === candidate.id
          )

          return (
            <button
              key={candidate.id}
              type="button"
              role="radio"
              aria-checked={selected}
              disabled={recorded}
              className={cn(
                "flex w-full items-center gap-2 rounded-lg px-2.5 py-2 text-left transition-colors duration-150 outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-default",
                selected ? "bg-secondary" : "hover:bg-muted/70"
              )}
              onClick={() => onSelectCandidate(candidate.id)}
            >
              <span
                aria-hidden="true"
                className={cn(
                  "flex size-4 shrink-0 items-center justify-center rounded-full border",
                  selected
                    ? "border-foreground bg-foreground text-background"
                    : "border-muted-foreground/50"
                )}
              >
                {selected ? <CheckIcon className="size-3" /> : null}
              </span>
              <span className="min-w-0 flex-1">
                <span className="block truncate text-xs font-medium">
                  {candidate.name}
                </span>
                <span className="block truncate text-[11px] text-muted-foreground">
                  {candidate.claimUnit} · {landedLine?.arrivalDays ?? "unknown"}{" "}
                  days
                </span>
              </span>
              <Badge variant="secondary">ready</Badge>
            </button>
          )
        })}
      </div>
      <Button
        type="button"
        size="lg"
        className="mt-4 w-full rounded-xl bg-foreground text-background hover:bg-foreground/85"
        disabled={!selectedCandidateId || recorded}
        onClick={onRecord}
      >
        {recorded ? "Decision recorded" : "Record Decision"}
      </Button>
      <p className="mt-2 text-[11px] text-muted-foreground">
        Recording is final. It does not place an order.
      </p>
    </div>
  )
}

